# 5. 字典：AI 文本词频统计实战
text = "AI 改变世界 Python 支撑 AI AI 依赖数据 数据 驱动 AI"
words = text.split()

freq = {}
for w in words:
    freq[w] = freq.get(w, 0) + 1

for word, count in sorted(freq.items(), key=lambda x: -x[1]):
    print(f"{word}: {count}次")

