# 6. 条件与循环：批量评定学生等级
scores = [95, 82, 67, 58, 74]

for s in scores:
    if s >= 90:
        grade = "优秀(A)"
    elif s >= 80:
        grade = "良好(B)"
    elif s >= 60:
        grade = "及格(C)"
    else:
        grade = "不及格(F)"
    print(f"分数 {s} -> 等级 {grade}")
